<script setup lang="ts">import { computed, onMounted, ref } from 'vue'; import { Search, Star } from 'lucide-vue-next'; import AppShell from '@/components/AppShell.vue'; import { memoryService, type Memory } from '@/services/memory-service'; const items=ref<Memory[]>([]); const query=ref(''); const loading=ref(true); const filtered=computed(()=>items.value.filter(m=>`${m.title} ${m.content}`.toLowerCase().includes(query.value.toLowerCase()))); onMounted(async()=>{items.value=await memoryService.list();loading.value=false});</script>
<template><AppShell><div class="page"><header><p class="text-sm font-medium text-nemu-600 dark:text-[#83d8b2]">Your memory</p><h1 class="mt-2 text-3xl font-semibold tracking-[-.035em]">Memories</h1></header><label class="surface mt-7 flex items-center gap-3 rounded-2xl border border-line px-4 py-3"><Search :size="19" class="text-muted"/><input v-model="query" class="w-full bg-transparent text-[16px] outline-none placeholder:text-muted" placeholder="Cari memory" /></label><div class="mt-5 flex gap-2"><button class="rounded-full bg-nemu-600 px-3 py-1.5 text-sm font-semibold text-white">All</button><button class="rounded-full border border-line px-3 py-1.5 text-sm text-muted">Recent</button><button class="rounded-full border border-line px-3 py-1.5 text-sm text-muted">Favorites</button></div><div v-if="loading" class="mt-8 space-y-1"><div v-for="n in 4" :key="n" class="h-20 animate-pulse rounded-xl bg-black/5 dark:bg-white/5" /></div><div v-else-if="filtered.length" class="mt-6 divide-y divide-line"><RouterLink v-for="memory in filtered" :key="memory.id" :to="`/memories/${memory.id}`" class="flex min-h-22 items-center justify-between gap-4 py-4"><div class="min-w-0"><p class="truncate font-semibold">{{ memory.title }}</p><p class="mt-1 truncate text-sm text-muted">{{ memory.content }}</p><p class="mt-1.5 text-xs text-muted">Saved {{ memory.createdAt }}</p></div><Star v-if="memory.favorite" :size="17" class="shrink-0 fill-nemu-500 text-nemu-500" /></RouterLink></div><section v-else class="mt-16 text-center"><p class="font-semibold">Tidak menemukan memory yang cocok.</p><p class="mt-2 text-sm text-muted">Coba gunakan kata yang berbeda.</p></section></div></AppShell></template>
